WITH metrics_long AS (SELECT * FROM (SELECT id, supplier_id, price, cost FROM products) src UNPIVOT (value FOR metric IN (price, cost)) unp) SELECT CASE WHEN value >= 64 THEN 'LARGE' ELSE 'SMALL' END AS value_tier, SIZE(COLLECT_SET(metric)) AS num_metrics, PERCENTILE_APPROX(value, ARRAY(0.25, 0.5, 0.75)) AS value_quartiles FROM metrics_long GROUP BY CASE WHEN value >= 64 THEN 'LARGE' ELSE 'SMALL' END ORDER BY num_metrics DESC
